def coherence_guard(message, max_pad_ratio=0.5):
    """HARD-mode style check: reject obvious good-word padding.
    Flags messages where too many low-context words are appended."""
    words = message.split()
    if len(words) < 5:
        return {"suspicious": False}

    # crude 'padding' heuristic: burst of short conversational fillers
    fillers = {"ok", "thanks", "later", "sure", "yeah", "meeting",
               "tomorrow", "sorry", "today", "see", "know"}
    pad = sum(1 for w in words if w.lower() in fillers)
    ratio = pad / len(words)
    return {"suspicious": ratio > max_pad_ratio, "pad_ratio": round(ratio, 2)}
